import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Menu, X, ArrowRight } from 'lucide-react';
import { Link as ScrollLink } from 'react-scroll';
import { Link, useNavigate } from 'react-router-dom';
import { SectionId } from '../types';

const Navbar: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'Services', to: SectionId.Services },
    { name: 'Process', to: SectionId.Process },
    { name: 'Audit', to: SectionId.Audit },
  ];

  return (
    <nav className={`fixed top-0 left-0 w-full z-50 transition-all duration-300 ${isScrolled ? 'py-4' : 'py-6'}`}>
      <div className="max-w-7xl mx-auto px-6 md:px-12">
        <div className={`glass rounded-2xl md:rounded-full px-6 py-3 flex items-center justify-between transition-all duration-300 ${isScrolled ? 'shadow-xl border-white/10' : 'bg-transparent border-transparent'}`}>

          <div className="flex items-center gap-2 cursor-pointer" onClick={() => navigate('/')}>
            <div className="w-10 h-10 bg-gradient-to-br from-[#3B82F6] to-[#F97316] rounded-xl flex items-center justify-center font-black text-white text-xl">A</div>
            <span className="text-xl font-bold tracking-tight text-white hidden sm:block">AVARTAH</span>
          </div>

          <div className="hidden md:flex items-center gap-8">
            {navLinks.map((link) => (
              <ScrollLink
                key={link.to}
                to={link.to}
                smooth={true}
                offset={-100}
                className="text-[#94A3B8] hover:text-[#3B82F6] cursor-pointer font-medium transition-colors"
              >
                {link.name}
              </ScrollLink>
            ))}
            <Link to="/admin" className="text-xs text-[#94A3B8] hover:text-white underline opacity-50">Admin</Link>
          </div>

          <div className="flex items-center gap-4">
            <ScrollLink
              to={SectionId.Audit}
              smooth={true}
              offset={-100}
              className="hidden md:flex items-center gap-2 px-6 py-2.5 bg-[#F97316] hover:bg-[#F97316]/90 text-white rounded-full font-bold text-sm transition-all transform hover:scale-105 active:scale-95 glow-orange"
            >
              Get Audit <ArrowRight size={16} />
            </ScrollLink>

            <button 
              className="md:hidden text-white"
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            >
              {isMobileMenuOpen ? <X size={28} /> : <Menu size={28} />}
            </button>
          </div>
        </div>
      </div>

      <AnimatePresence>
        {isMobileMenuOpen && (
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            className="absolute top-full left-0 w-full p-6 md:hidden"
          >
            <div className="glass rounded-2xl p-6 flex flex-col gap-6">
              {navLinks.map((link) => (
                <ScrollLink
                  key={link.to}
                  to={link.to}
                  smooth={true}
                  offset={-100}
                  onClick={() => setIsMobileMenuOpen(false)}
                  className="text-lg font-semibold text-white border-b border-white/10 pb-2"
                >
                  {link.name}
                </ScrollLink>
              ))}
              <ScrollLink
                to={SectionId.Audit}
                smooth={true}
                offset={-100}
                onClick={() => setIsMobileMenuOpen(false)}
                className="flex items-center justify-center gap-2 px-6 py-4 bg-[#F97316] text-white rounded-xl font-bold glow-orange"
              >
                Get Audit <ArrowRight size={18} />
              </ScrollLink>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </nav>
  );
};

export default Navbar;

