import { Lead, AuditFormData } from '../types';

const STORAGE_KEY = 'avartah_leads';

const initialLeads: Lead[] = [
  {
    id: '1',
    name: 'Sarah Chen',
    email: 'sarah@fintech-flow.io',
    company: 'FinTech Flow',
    website: 'https://fintech-flow.io',
    serviceInterest: 'Full Stack Development',
    budget: '$25k - $50k',
    status: 'new',
    createdAt: new Date().toISOString(),
  },
  {
    id: '2',
    name: 'Marcus Miller',
    email: 'marcus@nexustech.com',
    company: 'Nexus Tech',
    website: 'https://nexus-tech.com',
    serviceInterest: 'Growth Funnel Audit',
    budget: '$50k+',
    status: 'contacted',
    createdAt: new Date(Date.now() - 86400000).toISOString(),
  },
];

export const getLeads = (): Lead[] => {
  const stored = localStorage.getItem(STORAGE_KEY);
  if (!stored) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(initialLeads));
    return initialLeads;
  }
  return JSON.parse(stored);
};

export const saveLead = (data: AuditFormData): Lead => {
  const leads = getLeads();
  const newLead: Lead = {
    ...data,
    id: Math.random().toString(36).substr(2, 9),
    status: 'new',
    createdAt: new Date().toISOString(),
  };
  const updated = [newLead, ...leads];
  localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
  return newLead;
};

export const updateLeadStatus = (id: string, status: Lead['status']): void => {
  const leads = getLeads();
  const updated = leads.map(l => l.id === id ? { ...l, status } : l);
  localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
};

export const deleteLead = (id: string): void => {
  const leads = getLeads();
  const updated = leads.filter(l => l.id !== id);
  localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
};

