import express from 'express';
import cors from 'cors';
import bodyParser from 'body-parser';
import { z } from 'zod';
import { PrismaClient } from '@prisma/client';
import { Resend } from 'resend';

const app = express();
const PORT = process.env.PORT || 3000;

// Initialize clients
// In a real environment, Prisma and Resend would be configured via environment variables
const prisma = new PrismaClient();
const resend = new Resend(process.env.RESEND_API_KEY || 're_placeholder_key');

// Middleware configuration
app.use(cors());
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));

// Validation Schema
const AuditRequestSchema = z.object({
  websiteUrl: z.string().url({ message: "Invalid website URL" }),
  email: z.string().email({ message: "Invalid work email" }),
  businessName: z.string().min(2, { message: "Business name is too short" }),
  phoneNumber: z.string().optional(),
  budgetRange: z.string().min(1, { message: "Budget range is required" }),
});

// Health Check
app.get('/health', (req, res) => {
  res.status(200).json({
    status: 'OK',
    message: 'Avartah Solutions Backend Foundation is active',
    timestamp: new Date().toISOString()
  });
});

// Submit Audit Route
app.post('/api/submit-audit', async (req, res) => {
  try {
    // 1. Validate incoming data
    const validatedData = AuditRequestSchema.parse(req.body);

    // 2. Persist to Database via Prisma
    const newLead = await prisma.lead.create({
      data: {
        websiteUrl: validatedData.websiteUrl,
        email: validatedData.email,
        businessName: validatedData.businessName,
        phoneNumber: validatedData.phoneNumber,
        budgetRange: validatedData.budgetRange,
        status: 'PENDING'
      }
    });

    // 3. Trigger Transactional Email via Resend
    try {
      await resend.emails.send({
        from: 'Avartah Solutions <audits@avartah.com>',
        to: [validatedData.email],
        subject: 'Confirmed: Your Growth Audit Request',
        html: `
          <div style="font-family: sans-serif; color: #1e293b; max-width: 600px; margin: 0 auto;">
            <h1 style="color: #3b82f6;">Hello ${validatedData.businessName} Team,</h1>
            <p style="font-size: 16px; line-height: 1.5;">
              Thank you for requesting a Growth Audit from Avartah Solutions. We have received your details for 
              <strong>${validatedData.websiteUrl}</strong>.
            </p>
            <p style="font-size: 16px; line-height: 1.5;">
              Our senior engineering and strategy team is currently reviewing your digital stack. 
              You can expect a detailed report in your inbox within 24-48 hours.
            </p>
            <hr style="border: none; border-top: 1px solid #e2e8f0; margin: 24px 0;" />
            <p style="font-size: 14px; color: #64748b;">
              Avartah Solutions | Silicon Valley, CA<br />
              Architecting High-Performance Futures.
            </p>
          </div>
        `
      });
    } catch (emailError) {
      console.error('[Backend] Email sending failed:', emailError);
      // We don't fail the whole request if only the email fails, 
      // as the lead is already saved in the DB.
    }

    // 4. Return success response
    return res.status(201).json({
      success: true,
      message: 'Audit request received successfully',
      leadId: newLead.id
    });

  } catch (error) {
    if (error instanceof z.ZodError) {
      return res.status(400).json({
        success: false,
        errors: error.errors.map(err => ({ field: err.path[0], message: err.message }))
      });
    }

    console.error('[Backend] Submit Audit Error:', error);
    return res.status(500).json({
      success: false,
      message: 'An internal server error occurred while processing your request.'
    });
  }
});

// Start the server
app.listen(PORT, () => {
  console.log(`[Backend] Server initialized and listening on port ${PORT}`);
});

