import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Menu, X, ArrowRight } from 'lucide-react';
import { Link as ScrollLink } from 'react-scroll';
import { useNavigate } from 'react-router-dom';
import { SectionId } from '../types';

const Navbar: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'Why Us', to: SectionId.Services },
    { name: 'Process', to: SectionId.Process },
    { name: 'Live Session', to: SectionId.Booking },
  ];

  return (
    <nav className={`fixed top-0 left-0 w-full z-50 transition-all duration-300 ${isScrolled ? 'py-4' : 'py-6'}`}>
      <div className="max-w-7xl mx-auto px-6 md:px-12">
        <div className={`glass-effect rounded-full px-6 py-3 flex items-center justify-between transition-all duration-300 ${isScrolled ? 'shadow-xl border-white/10' : 'bg-transparent border-transparent'}`}>

          <div className="flex items-center gap-2 cursor-pointer" onClick={() => navigate('/')}>
            <div className="w-8 h-8 bg-gradient-to-br from-electric to-sunset rounded-lg flex items-center justify-center font-black text-white text-lg shadow-lg shadow-electric/20">A</div>
            <span className="text-xl font-extrabold tracking-tighter text-white">AVARTAH</span>
          </div>

          <div className="hidden md:flex items-center gap-8">
            {navLinks.map((link) => (
              <ScrollLink
                key={link.to}
                to={link.to}
                smooth={true}
                offset={-100}
                className="text-muted hover:text-electric cursor-pointer font-medium transition-colors text-sm uppercase tracking-wider"
              >
                {link.name}
              </ScrollLink>
            ))}
          </div>

          <div className="flex items-center gap-4">
            <ScrollLink
              to={SectionId.Audit}
              smooth={true}
              offset={-100}
              className="hidden md:flex items-center gap-2 px-6 py-2 bg-sunset hover:bg-sunset/90 text-white rounded-full font-bold text-sm transition-all transform hover:scale-105 active:scale-95 glow-orange cursor-pointer"
            >
              Free Audit
            </ScrollLink>

            <button 
              className="md:hidden text-white p-2"
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            >
              {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
          </div>
        </div>
      </div>

      <AnimatePresence>
        {isMobileMenuOpen && (
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            className="absolute top-full left-0 w-full p-6 md:hidden"
          >
            <div className="glass-effect rounded-2xl p-6 flex flex-col gap-4">
              {navLinks.map((link) => (
                <ScrollLink
                  key={link.to}
                  to={link.to}
                  smooth={true}
                  offset={-100}
                  onClick={() => setIsMobileMenuOpen(false)}
                  className="text-lg font-semibold text-white border-b border-white/5 pb-2"
                >
                  {link.name}
                </ScrollLink>
              ))}
              <ScrollLink
                to={SectionId.Audit}
                smooth={true}
                offset={-100}
                onClick={() => setIsMobileMenuOpen(false)}
                className="flex items-center justify-center gap-2 px-6 py-4 bg-sunset text-white rounded-xl font-bold glow-orange"
              >
                Get My Free Audit <ArrowRight size={18} />
              </ScrollLink>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </nav>
  );
};

export default Navbar;

