import { motion } from 'framer-motion';
import GlassCard from './GlassCard';
import { ClipboardCheck, Search, FileText, Rocket, ChevronRight } from 'lucide-react';

const steps = [
  {
    day: 'Day 1-2',
    title: 'Digital Submission',
    description: 'We perform a deep-crawl of your entire technical stack, indexing every bottleneck and performance leak.',
    icon: <ClipboardCheck className="text-electric" size={24} />,
    color: 'electric'
  },
  {
    day: 'Day 3-5',
    title: 'Forensic Analysis',
    description: 'Our engineers analyze heatmap data and conversion logs to find exactly where you are losing revenue.',
    icon: <Search className="text-electric" size={24} />,
    color: 'electric'
  },
  {
    day: 'Day 6-8',
    title: 'Correction Document',
    description: 'Receive a brutal, logic-based audit document outlining every technical flaw in your current funnel.',
    icon: <FileText className="text-sunset" size={24} />,
    color: 'orange'
  },
  {
    day: 'Day 9-10',
    title: 'Rebuild Strategy',
    description: 'A 1:1 blueprint session to map out the 2.5X growth engine tailored specifically for your business.',
    icon: <Rocket className="text-sunset" size={24} />,
    color: 'orange'
  }
];

const Process: React.FC = () => {
  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 relative">
      {/* Connecting Line (Desktop) */}
      <div className="hidden lg:block absolute top-1/2 left-0 w-full h-0.5 bg-gradient-to-r from-electric/20 via-sunset/20 to-transparent -translate-y-1/2 -z-10" />

      {steps.map((step, index) => (
        <motion.div
          key={index}
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: index * 0.1 }}
          viewport={{ once: true }}
        >
          <GlassCard 
            hoverGlow={step.color as 'blue' | 'orange'} 
            className="h-full border-white/5 relative group"
          >
            <div className="absolute -top-3 -left-3 px-4 py-1 rounded-full bg-midnight border border-white/10 text-[10px] font-black tracking-widest uppercase text-muted group-hover:text-white transition-colors">
              {step.day}
            </div>

